mapper.select:
select view_id, user_id, biz_type, biz_id, view_time, last_view_time, view_count
from user_view_history
where user_id = #{userId} and biz_type = #{bizType} and biz_id = #{bizId}

mapper.update:
update user_view_history
set view_count = view_count + 1, last_view_time = now()
where view_id = #{viewId}

mapper.select:
select * from (
select h.view_id, h.biz_type, h.biz_id, b.title, b.cover_url as cover_object_key, b.create_by as author_name, h.view_time, h.last_view_time, h.view_count from user_view_history h inner join blog b on b.blog_id = h.biz_id where h.user_id = #{userId} and h.biz_type = 'BLOG' and h.biz_type = #{bizType}
union all
select h.view_id, h.biz_type, h.biz_id, a.title, a.cover_object_key, u.nick_name as author_name, h.view_time, h.last_view_time, h.view_count from user_view_history h inner join article a on a.article_id = h.biz_id left join sys_user u on u.user_id = a.author_id where h.user_id = #{userId} and h.biz_type = 'ARTICLE' and h.biz_type = #{bizType}
union all
select h.view_id, h.biz_type, h.biz_id, a.title, a.cover_object_key, u.nick_name as author_name, h.view_time, h.last_view_time, h.view_count from user_view_history h inner join chapter c on c.chapter_id = h.biz_id inner join article a on a.article_id = c.article_id left join sys_user u on u.user_id = a.author_id where h.user_id = #{userId} and h.biz_type = 'CHAPTER' and h.biz_type = #{bizType}
union all
select h.view_id, h.biz_type, h.biz_id, r.title, cast(null as char) as cover_object_key, u.nick_name as author_name, h.view_time, h.last_view_time, h.view_count from user_view_history h inner join resource r on r.resource_id = h.biz_id left join sys_user u on u.user_id = r.author_id where h.user_id = #{userId} and h.biz_type = 'RESOURCE' and h.biz_type = #{bizType}
union all
select h.view_id, h.biz_type, h.biz_id, p.title, cast(null as char) as cover_object_key, u.nick_name as author_name, h.view_time, h.last_view_time, h.view_count from user_view_history h inner join project p on p.project_id = h.biz_id left join sys_user u on u.user_id = p.author_id where h.user_id = #{userId} and h.biz_type = 'PROJECT' and h.biz_type = #{bizType} ) t order by t.last_view_time desc, t.view_id desc
